/* Rasterize original deterministic scene paint once, then reuse miniature sprites. */
(()=>{'use strict';
let campus=null,ground=null;const sprites=new Map(),stats={grounds:0,sprites:0,hits:0};
function make(w,h){let c;if(typeof OffscreenCanvas==='function')c=new OffscreenCanvas(w,h);else if(typeof HTMLCanvasElement!=='undefined'){c=document.createElement('canvas');c.width=w;c.height=h;}if(!c)return null;return c;}
function begin(id){if(campus===id)return;campus=id;ground=null;sprites.clear();}
function polygon(ctx,pts,fill,stroke){ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=.6;ctx.stroke();}}
function geometry(ctx,iso,shade){const poly=(pts,fill,stroke)=>polygon(ctx,pts,fill,stroke);return{iso,shade,poly,box(x,y,w,h,z,wall,roof){const a=iso(x,y),b=iso(x+w,y),c=iso(x+w,y+h),d=iso(x,y+h);poly([[d.x,d.y],[c.x,c.y],[c.x,c.y-z],[d.x,d.y-z]],wall);poly([[b.x,b.y],[c.x,c.y],[c.x,c.y-z],[b.x,b.y-z]],shade(wall,-28));poly([[a.x,a.y-z],[b.x,b.y-z],[c.x,c.y-z],[d.x,d.y-z]],roof);return{a,b,c,d};}};}
function drawGround(ctx,paint){const bounds={x:-1590,y:-530,w:3180,h:2010};if(!ground){const c=make(bounds.w,bounds.h);if(!c){paint(ctx);return false;}const p=c.getContext('2d');p.translate(-bounds.x,-bounds.y);paint(p);ground={canvas:c,...bounds};stats.grounds++;}else stats.hits++;ctx.drawImage(ground.canvas,ground.x,ground.y,ground.w,ground.h);return true;}
function building(ctx,b,env){if(!window.CampusArchitecture)return false;const key=[b.x,b.y,b.w,b.h,b.height,b.wall,b.roof,b.style,b.type].join('|');if(sprites.has(key)){const s=sprites.get(key);if(!s)return false;ctx.drawImage(s.canvas,s.x,s.y,s.w,s.h);stats.hits++;return true;}
 const c0=env.iso(b.x,b.y),c1=env.iso(b.x+b.w,b.y),c2=env.iso(b.x+b.w,b.y+b.h),c3=env.iso(b.x,b.y+b.h),xs=[c0.x,c1.x,c2.x,c3.x],ys=[c0.y,c1.y,c2.y,c3.y];
 const x=Math.floor(Math.min(...xs)-75),y=Math.floor(Math.min(...ys)-(b.height||74)-155),w=Math.ceil(Math.max(...xs)-x+95),h=Math.ceil(Math.max(...ys)-y+72),ratio=1.5,c=make(Math.ceil(w*ratio),Math.ceil(h*ratio));if(!c)return false;
 const p=c.getContext('2d');p.setTransform(ratio,0,0,ratio,-x*ratio,-y*ratio);const handled=window.CampusArchitecture.draw(p,b,geometry(p,env.iso,env.shade));if(!handled){sprites.set(key,null);return false;}const s={canvas:c,x,y,w,h};sprites.set(key,s);stats.sprites++;ctx.drawImage(c,x,y,w,h);return true;}
function clear(){ground=null;sprites.clear();campus=null;}
function prop(ctx,item,key,env){if(!Number.isFinite(item.x)||!Number.isFinite(item.y))return false;const cacheKey='prop|'+key;if(sprites.has(cacheKey)){const s=sprites.get(cacheKey);ctx.drawImage(s.canvas,s.x,s.y,s.w,s.h);stats.hits++;return true;}const p0=env.iso(item.x,item.y),x=Math.floor(p0.x-145),y=Math.floor(p0.y-245),w=310,h=300,ratio=1.35,c=make(Math.ceil(w*ratio),Math.ceil(h*ratio));if(!c)return false;const p=c.getContext('2d');p.setTransform(ratio,0,0,ratio,-x*ratio,-y*ratio);item.draw(p);const s={canvas:c,x,y,w,h};sprites.set(cacheKey,s);stats.sprites++;ctx.drawImage(c,x,y,w,h);return true;}
window.ScenePaint={begin,ground:drawGround,building,prop,geometry,clear,stats};})();
